contract InvMutTest {
    C c;
    address owner;

    constructor(C _c) { c = _c; owner = address(this); }

    // We take inputs: whether to perform a deposit first and amount to send as deposit,
    // and whether to attempt a withdrawAll and an amount to send in sendMoney.
    function run(bool doDeposit, uint depositAmt, bool doWithdrawAll, bool doSendMoney, address sendTarget, uint sendAmt) public payable {
        // If we want to send Ether to c for deposit, ensure this contract has enough balance
        if (doDeposit) {
            require(address(this).balance >= depositAmt);
            // call receive by sending Ether
            c.f{value: depositAmt}();
        }

        // Observe state before potentially destructive calls
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Only the owner (this contract) should be allowed to call withdrawAll/withdraw/sendMoney.
        // Attempt withdrawAll and record whether it reverted
        bool withdrawAllReverted;
        if (doWithdrawAll) {
            try c.withdrawAll() {
                withdrawAllReverted = false;
            } catch {
                withdrawAllReverted = true;
            }
        }

        // Attempt sendMoney and record revert
        bool sendMoneyReverted;
        if (doSendMoney) {
            try c.sendMoney(sendTarget, sendAmt) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        }

        // After operations observe state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule to assert:
        // 1) depositsCount never decreases (it is monotonic non-decreasing)
        // 2) If withdrawAll was called successfully (did not revert), contract balance becomes zero
        // 3) Only owner (this contract) can perform withdrawAll/sendMoney: since this contract is owner, successful calls are allowed; if call reverted that is allowed too.
        // Combine into single assert expression:
        assert((afterDeposits >= beforeDeposits) &&
               (!(doWithdrawAll && !withdrawAllReverted) || afterBalance == 0));
    }

    // allow receiving Ether
    receive() external payable {}
}

