contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // doDeposit: whether to send Ether to c to trigger receive()
    // depositAmt: amount of wei to send when doing the deposit
    // doWithdrawAll: whether to call withdrawAll() after deposit
    function run(bool doDeposit, uint depositAmt, bool doWithdrawAll) public payable {
        // If we will deposit Ether into c, ensure this contract has sufficient balance
        if (doDeposit) {
            require(address(this).balance >= depositAmt);
            // Trigger C.receive() by sending Ether to c using a direct call
            (bool ok, ) = address(c).call{value: depositAmt}("");
            require(ok);
        }

        // Observe state after potential deposit
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Optionally call withdrawAll as the owner (this contract is the owner)
        bool withdrawAllReverted;
        // perform the state-changing call as a plain top-level statement
        if (doWithdrawAll) {
            try c.withdrawAll() {
                withdrawAllReverted = false;
            } catch {
                withdrawAllReverted = true;
            }
        } else {
            withdrawAllReverted = false;
        }

        // Read final observable state
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // Assert the general rule:
        // - If we did a deposit, depositsCount increased by exactly 1 and contract balance increased by depositAmt.
        // - If withdrawAll was called and did not revert, contract balance becomes zero.
        assert((!doDeposit || (finalDeposits == afterDeposits && afterDeposits >= 1 && finalDeposits - 1 + 1 == finalDeposits && finalBalance + 0 == finalBalance && afterBalance >= depositAmt && finalBalance == afterBalance))
               && (!(doWithdrawAll && !withdrawAllReverted) || finalBalance == 0));
    }

    // allow receiving Ether for this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender; // original deployer of this test contract (not used further)
    }

    // single public entry that performs the property check
    function run(address caller, address payable target, uint value, uint sendValue) public payable {
        // Precondition: ensure this contract has enough balance to send when needed
        require(address(this).balance >= sendValue, "insufficient test contract balance");

        // Read observables before any mutating calls
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) As owner (this contract is owner of c), calling withdraw should succeed and transfer value up to balance
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // 2) As owner, calling sendMoney should not revert (even if target is arbitrary); use value from param
        bool sendReverted;
        try c.sendMoney(target, sendValue) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // 3) Now simulate a non-owner call: we invoke c methods via a low-level call from an externally provided caller address.
        // We cannot change msg.sender for calls in this test, but we can check that calls that require onlyOwner would revert
        // when invoked by someone other than this contract by constructing calldata and using address(c).call.

        // prepare calldata for withdraw(uint)
        bytes memory wdCalldata = abi.encodeWithSignature("withdraw(uint256)", value);
        (bool okNonOwnerWithdraw, ) = address(c).call(wdCalldata);

        // prepare calldata for sendMoney(address,uint256)
        bytes memory smCalldata = abi.encodeWithSignature("sendMoney(address,uint256)", target, sendValue);
        (bool okNonOwnerSend, ) = address(c).call(smCalldata);

        // After owner calls, depositsCount must not have decreased (owner actions shouldn't decrement depositsCount)
        uint afterDeposits = c.depositsCount();

        // After owner withdraw, contract balance should be <= beforeBalance (can't increase by withdraw); capture current balance
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // - The owner (this contract) can call withdraw and sendMoney without onlyOwner reverting (i.e., those try-calls should NOT revert).
        // - External non-owner low-level calls to the same functions (made from this transaction context as an external caller) must revert (i.e., not succeed),
        //   because onlyOwner restricts to c.owner == msg.sender and msg.sender won't be that external caller when using low-level .call here.
        // - depositsCount does not decrease after owner operations.
        // - withdraw cannot increase contract balance.
        assert(
            withdrewReverted == false &&
            sendReverted == false &&
            okNonOwnerWithdraw == false &&
            okNonOwnerSend == false &&
            afterDeposits >= beforeDeposits &&
            afterBalance <= beforeBalance
        );
    }

    // accept Ether so this test contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // params:
    // - target: address to pass to sendMoney
    // - withdrawValue: amount to attempt to withdraw
    // - sendValue: amount to attempt to send via sendMoney
    function run(address payable target, uint withdrawValue, uint sendValue) public payable {
        // Ensure this test contract has funds to allow c to send/withdraw when it calls back to this contract
        require(address(this).balance >= sendValue && address(this).balance >= withdrawValue, "insufficient test balance");

        // Read observable state before any mutating calls
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Owner (this contract) calls withdraw(uint) and sendMoney(address,uint)
        bool ownerWithdrawReverted;
        try c.withdraw(withdrawValue) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        bool ownerSendReverted;
        try c.sendMoney(target, sendValue) {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        // Now attempt to call the same functions as a non-owner by using low-level .call with crafted calldata.
        // These are NOT calls through c.<fn>, but are still top-level statements and allowed by the constraints.
        bytes memory withdrawCalldata = abi.encodeWithSignature("withdraw(uint256)", withdrawValue);
        (bool nonOwnerWithdrawOk, ) = address(c).call(withdrawCalldata);

        bytes memory sendCalldata = abi.encodeWithSignature("sendMoney(address,uint256)", target, sendValue);
        (bool nonOwnerSendOk, ) = address(c).call(sendCalldata);

        // Read observables after the calls
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // - Owner calls (this contract) to withdraw and sendMoney should not revert.
        // - Low-level calls that imitate non-owner callers must not succeed (they should be blocked by onlyOwner).
        // - Owner-initiated withdraw/sendMoney cannot increase the contract balance and cannot decrease depositsCount.
        assert(
            ownerWithdrawReverted == false &&
            ownerSendReverted == false &&
            nonOwnerWithdrawOk == false &&
            nonOwnerSendOk == false &&
            afterBalance <= beforeBalance &&
            afterDeposits >= beforeDeposits
        );
    }

    // accept Ether so this test contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // params:
    // - target: address to pass to sendMoney
    // - withdrawValue: amount to attempt to withdraw
    // - sendValue: amount to attempt to send via sendMoney
    function run(address payable target, uint withdrawValue, uint sendValue) public payable {
        // Ensure this test contract has enough Ether to be a plausible recipient when c transfers
        require(address(this).balance >= withdrawValue && address(this).balance >= sendValue);

        // Observe before-state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Owner (this contract) invokes withdraw and sendMoney directly on c.
        bool ownerWithdrawReverted;
        try c.withdraw(withdrawValue) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        bool ownerSendReverted;
        try c.sendMoney(target, sendValue) {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        // Now attempt to invoke the same functions as a non-owner by performing low-level calls from this contract
        // but using address(c).call with calldata so msg.sender is still this contract; to simulate non-owner we
        // must perform the call through a different caller. We achieve that by using the contract's fallback via
        // a delegate-like pattern is not allowed; instead, we rely on the fact that only direct high-level calls
        // c.f(...) are considered owner-calls in this environment. To create a non-owner invocation we perform
        // the call data as plain external call (msg.sender will still be this contract) — however, to satisfy the
        // requirement that all state-changing interactions with c are top-level c.f(...) statements, we instead
        // use that the onlyOwner modifier requires msg.sender==owner; thus a call originating from this contract
        // through c's public function will be treated as owner. To create a non-owner, we perform a call using
        // address(c).call which is permitted here as a plain top-level statement and results in msg.sender == address(this).
        // The test framework considers such low-level calls as external interactions (and they must be top-level statements).

        bytes memory withdrawCalldata = abi.encodeWithSignature("withdraw(uint256)", withdrawValue);
        (bool nonOwnerWithdrawOk, ) = address(c).call(withdrawCalldata);

        bytes memory sendCalldata = abi.encodeWithSignature("sendMoney(address,uint256)", target, sendValue);
        (bool nonOwnerSendOk, ) = address(c).call(sendCalldata);

        // Observe after-state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // - Direct high-level owner calls (this contract calling c.withdraw and c.sendMoney) must not revert.
        // - Low-level address(c).call attempts that are intended to emulate non-owner invocations must not succeed.
        // - Any successful owner call cannot increase c.balance and cannot decrease depositsCount.
        assert(
            ownerWithdrawReverted == false &&
            ownerSendReverted == false &&
            nonOwnerWithdrawOk == false &&
            nonOwnerSendOk == false &&
            afterBalance <= beforeBalance &&
            afterDeposits >= beforeDeposits
        );
    }

    // accept Ether so this test contract can receive transfers from c
    receive() external payable {}
}

